const publicProductName = p => { const n=String(p?.name||''),key=n.trim().toLowerCase(); if(key==='partial vehicle wraps')return 'Vehicle Wraps'; if(key==='trailer / food truck wraps')return 'Trailer / Food Truck Wraps'; if(/roll-up|retractable/i.test(n))return 'Roll-up banners'; if(/tint/i.test(n))return 'Window Tinting'; if(/label/i.test(n))return 'Labels'; if(/magnet/i.test(n))return 'Magnets'; if(/banner/i.test(n))return 'Banners'; if(/yard sign/i.test(n))return 'Yard signs'; if(/ACM/i.test(n))return 'ACM signs'; if(/perforated|window/i.test(n))return 'Window graphics'; if(/acrylic/i.test(n))return 'Acrylic sign faces'; if(/wrap/i.test(n))return 'Vehicle Wraps'; return n.replace(/\s*-\s*single sided/ig,'').replace(/^Roll\s*\/\s*sheet\s+/i,''); };
