 product:async(f,d)=>{const p=state.editProduct;const config={...p.config};for(const key of ['unit','description','sell_per_sqft','cost_per_sqft','minimum_price','setup_price','setup_cost','waste_percent','labor_minutes_per_unit','min_width','min_height','default_width','default_height','max_width','max_height','min_quantity','max_quantity'])config[key]=d[key];config.instant=!!d.instant;config.supports_multiple_dimensions=!!d.supports_multiple_dimensions;config.self_approve_artwork=!!d.self_approve_artwork;config.requires_installation=!!d.requires_installation;config.is_wrap=!!d.is_wrap;config.tiers=d.tiers.split('\n').map(x=>x.trim()).filter(Boolean).map(line=>{const [from,multiplier]=line.split(':');if(!from||!multiplier)throw new Error('Each quantity band must use start:multiplier.');return {from:Number(from),multiplier:multiplier.trim()};});const body={name:d.name,category:d.category,workflow_id:Number(d.workflow_id),active:!!d.active,public:!!d.public,config,version:p.version};await api('/api/admin/products'+(p.id?'/'+p.id:''),p.id?'PUT':'POST',body);state.catalog=await api('/api/catalog');closeModal();toast('Product saved. Existing jobs remain unchanged.');await loadProducts();},
